/* v8: one workbench, gesture timeline, non-modal simulated dictation. */
let composerVisible=false,composerExpanded=false;
let pageDockOpen=false;
function pageDockAction(){if(!pageDockOpen){pageDockOpen=true;mountVoice();return;}pageDockOpen=false;go(S.page==='home'?'overview':'home');}
let dictationTimer=null,dictationIndex=0,dictationBase='',dictationSample='';
const DICTATION_SAMPLES=['牛奶照旧，蔬菜减半；接奶奶的餐厅先别订。','继续关注蒸烤箱的优惠，有合适的方案再告诉我。','帮我整理周末带小包出门要带的东西。'];
function initWorkbench(){if(!S.v8){S.workFilter='all';S.workFolds={};S.topicOpen.care=false;S.timelineWidth=108;S.page='overview';S.v8=true;}S.workFolds||={};S.dictationText||='';S.timelineWidth||=108;}
initWorkbench();
function unresolvedAssistance(t){return (t.confirmations||[]).some(q=>!q.answer&&q.kind!=='offline');}
function assistance(t){return t.archive!=='archived'&&!['cancelled','paused'].includes(t.status)&&(unresolvedAssistance(t)||t.status==='error'||(t.status==='wait_user'&&!t.person));}
function personalTodo(t){return t.archive!=='archived'&&t.person===true&&!terminal(t.status)&&t.status!=='paused'&&!assistance(t);}
function actionHint(t){if(assistance(t)){const q=(t.confirmations||[]).find(q=>!q.answer);return q?.actionLabel||(/支付/.test(q?.question||'')?'请您支付':t.status==='error'?'请您恢复登录':'请您确认信息');}return personalTodo(t)?'需本人到场 / 线下完成':'';}
function matchWork(t){return S.workFilter==='assist'?assistance(t):S.workFilter==='personal'?personalTodo(t):true;}
function workItems(){return S.items.filter(t=>S.showArchived?t.archive==='archived':t.archive!=='archived').filter(t=>matchWork(t)||S.instances.some(x=>x.parent===t.id&&matchWork(x)&&(S.showArchived?x.archive==='archived':x.archive!=='archived')));}
function workEvents(){return timelineEntries(S.items.filter(t=>S.showArchived?t.archive==='archived':t.archive!=='archived')).filter(matchWork);}
function setWorkFilter(filter){S.workFilter=filter;S.workFolds[filter]={};S.timelineScroll=null;save();render();}
function foldOpen(theme){const value=S.workFolds[S.workFilter]?.[theme];return value===undefined?false:value;}
function rememberWorkFold(theme,open){(S.workFolds[S.workFilter]||={})[decodeURIComponent(theme)]=open;save();}
function toggleWorkFolds(){const names=[...new Set(workItems().map(t=>t.theme))];const value=!names.every(foldOpen);S.workFolds[S.workFilter]=Object.fromEntries(names.map(n=>[n,value]));save();render();}
function workTopics(){if(S.topicTab==='care')return topicTabs()+carePanel();const items=workItems(),names=[...new Set([...S.topics,...items.map(t=>t.theme)])];return `${topicTabs()}<div class="work-topic-heading"><strong>${S.workFilter==='assist'?'需要您搭把手':S.workFilter==='personal'?'需要您线下参加':'按主题照看'}</strong><button onclick="toggleWorkFolds()">${names.filter(n=>items.some(t=>t.theme===n)).every(foldOpen)?'全部收起':'全部展开'}</button></div>${names.map(theme=>{const list=items.filter(t=>t.theme===theme).sort((a,b)=>Number(needUser(b))-Number(needUser(a))||(ts(b.created)||0)-(ts(a.created)||0));if(!list.length)return '';return `<details class="topic-fold" ${foldOpen(theme)?'open':''} ontoggle="rememberWorkFold('${encodeURIComponent(theme)}',this.open)"><summary><div class="topic-fold-title"><strong>${esc(theme)}</strong><span>${list.length} 件 <i>⌄</i></span></div><div class="fold-counts">${foldCounts(list)}</div></summary><div class="topic-content">${list.map(t=>overviewCard(t)+S.instances.filter(x=>x.parent===t.id&&x.archive!=='archived'&&!terminal(x.status)&&matchWork(x)).map(x=>`<button class="next-compact" onclick="detail('${x.id}')">${frequency(x)}<span>${esc(x.title)} · ${fmt(startAt(x))}</span>${badge(x)}</button>`).join('')).join('')}</div></details>`;}).join('')||'<div class="work-empty">这个分类暂时没有需要处理的事项。</div>'}${!items.length?'<p class="work-empty">目前没有这类事项，可以放心忙自己的。</p>':''}`;}
function workDates(){const today=new Date(Date.now()+28800000).toISOString().slice(0,10);const eventDates=workEvents().map(startDate).filter(Boolean).sort();const middle=Date.parse(today+'T12:00Z');const first=Math.min(middle-3*86400000,eventDates.length?Date.parse(eventDates[0]+'T12:00Z'):middle);const last=Math.max(middle+7*86400000,eventDates.length?Date.parse(eventDates.at(-1)+'T12:00Z'):middle);return Array.from({length:Math.round((last-first)/86400000)+1},(_,i)=>new Date(first+i*86400000).toISOString().slice(0,10));}
function workTimeline(){const dates=workDates(),events=workEvents(),today=new Date(now().getTime()+28800000).toISOString().slice(0,10);let h='<div class="timehead timecorner">时段</div>'+dates.map(d=>`<div class="timehead ${d===today?'today':''}" data-date="${d}">${d===today?'今天':d.slice(5).replace('-',' / ')}<strong>${['日','一','二','三','四','五','六'][new Date(d+'T12:00Z').getUTCDay()]}</strong></div>`).join('');['上午','下午','晚上'].forEach((label,p)=>{h+=`<div class="daypart">${label}</div>`;for(const date of dates){const list=events.filter(t=>startDate(t)===date&&startPart(t)===p).sort((a,b)=>ts(startAt(a))-ts(startAt(b)));h+=`<div class="timecell ${date===today?'today':''}">${list.map(t=>`<button class="timeitem ${t.status}" onclick="detail('${t.id}')"><small>${fmt(startAt(t)).slice(-5)} · ${t.startedAt?'启动':'预计'}</small><strong>${esc(t.title)}</strong><div class="row">${frequency(t)}<small>${t.status==='done'&&assistance(t)?'AI 已完成':STATUS[t.status]}</small></div>${actionHint(t)?`<span class="case-action ${personalTodo(t)?'offline':'assist'}">${esc(actionHint(t))}</span>`:''}</button>`).join('')||'<span class="time-empty">·</span>'}</div>`;}});return `<section class="work-calendar"><div class="work-calendar-caption"><strong>事情的时间表</strong><span>滑动浏览 · 双指缩放</span></div><div id="work-timeline" class="work-timeline" tabindex="0" aria-label="任务启动时间表，可单指滑动，双指缩放"><div id="work-grid" class="timegrid" style="--n:${dates.length};--cw:${S.timelineWidth}px">${h}</div></div><div class="work-legend">${icon('once')} 一次 ${icon('repeat')} 持续 ${icon('person')} 线下参加 <button onclick="iconHelp()" aria-label="图标说明">ⓘ</button><span>${events.filter(t=>!startAt(t)).length} 件启动时间待定</span></div></section>`;}
overview=function(){initWorkbench();const n=impact(),g=groupStats(S.items.filter(t=>t.archive!=='archived'));return `${workTimeline()}<details class="impact-collapsed" ${S.impactOpen?'open':''} ontoggle="S.impactOpen=this.open;save()"><summary>陪伴您的这些日子 <span>服务统计 ⌄</span></summary><div><p>陪伴 ${n.days} 天 · 累计照料 ${n.total} 项事</p><p>预估省时 ${n.hours} 小时 · 省钱示例 ${n.money} 元</p><button onclick="serviceReport()">查看照料报告 ↗</button><small>演示统计，详细口径见报告</small></div></details>${S.showArchived?'<div class="inline-notice">正在查看历史归档 <button onclick="S.showArchived=false;render()">返回当前</button></div>':''}${workTopics()}<div class="overview-bottom"><button onclick="archiveReview()">一起归档 · ${pending().length}</button><button onclick="showArchives()">历史记录 ↗</button></div>`;};
function bindWorkbenchGestures(){const sc=document.getElementById('work-timeline'),grid=document.getElementById('work-grid');if(!sc||!grid)return;if(!S.calendarZoomed){S.timelineWidth=Math.max(68,((sc.clientWidth||360)-34));grid.style.setProperty('--cw',S.timelineWidth+'px');}const dates=workDates(),today=new Date(Date.now()+28800000).toISOString().slice(0,10);sc.scrollLeft=S.timelineScroll??Math.max(0,dates.indexOf(today)*S.timelineWidth);sc.addEventListener('scroll',()=>{S.timelineScroll=sc.scrollLeft;},{passive:true});let pinch=null,ignoreClickUntil=0;const dist=e=>Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);const resize=(width,anchor)=>{const old=S.timelineWidth,next=Math.max(68,Math.min(640,width));grid.style.setProperty('--cw',next+'px');sc.scrollLeft=(sc.scrollLeft+anchor-34)*next/old+34-anchor;S.timelineWidth=next;S.calendarZoomed=true;S.timelineScroll=sc.scrollLeft;};sc.addEventListener('touchstart',e=>{if(e.touches.length===2){pinch={distance:dist(e),width:S.timelineWidth};}},{passive:true});sc.addEventListener('touchmove',e=>{if(e.touches.length!==2||!pinch)return;e.preventDefault();const rect=sc.getBoundingClientRect();resize(pinch.width*dist(e)/Math.max(pinch.distance,1),(e.touches[0].clientX+e.touches[1].clientX)/2-rect.left);ignoreClickUntil=Date.now()+400;},{passive:false});sc.addEventListener('touchend',e=>{if(e.touches.length<2){pinch=null;save();}},{passive:true});sc.addEventListener('click',e=>{if(Date.now()<ignoreClickUntil){e.stopPropagation();e.preventDefault();}},true);sc.addEventListener('wheel',e=>{if(e.ctrlKey||e.metaKey){e.preventDefault();resize(S.timelineWidth*Math.exp(-e.deltaY*.005),e.clientX-sc.getBoundingClientRect().left);save();}},{passive:false});}
function syncDictationField(){input=S.dictationText;const field=document.getElementById('input');if(field){field.value=input;field.scrollTop=field.scrollHeight;}save();}
function editDictation(value){S.dictationText=value;input=value;if(listening){dictationBase=value;dictationSample=dictationSample.slice(dictationIndex);dictationIndex=0;}save();}
function startDictation(id=''){if(listening){stopDictation();return;}composerVisible=true;composerExpanded=false;drawComposer();voiceContext=id||detailID||inputContext||'';inputContext=voiceContext;dictationBase=S.dictationText+(S.dictationText?'；':'');dictationSample=DICTATION_SAMPLES[(S.voiceSampleIndex||0)%DICTATION_SAMPLES.length];S.voiceSampleIndex=(S.voiceSampleIndex||0)+1;dictationIndex=0;listening=true;voiceOpen=true;mic=true;voiceText=S.dictationText;S.dictationText=dictationBase;syncDictationField();mountVoice();clearInterval(dictationTimer);dictationTimer=setInterval(()=>{if(!listening)return;if(dictationIndex<dictationSample.length){dictationIndex=Math.min(dictationSample.length,dictationIndex+2);S.dictationText=dictationBase+dictationSample.slice(0,dictationIndex);voiceText=S.dictationText;syncDictationField();}},180);}
function stopDictation(){clearInterval(dictationTimer);dictationTimer=null;listening=false;voiceOpen=false;mic=false;voiceText=S.dictationText;mountVoice();}
openVoice=function(id=''){startDictation(id);};record=function(){startDictation();};closeVoice=stopDictation;finishListening=stopDictation;
mountVoice=function(){const footerHeight=document.getElementById('footer').offsetHeight||(composerVisible?80:8);document.querySelector('.app').style.setProperty('--voice-bottom',(footerHeight+12)+'px');document.querySelector('.app').style.setProperty('--footer-space',footerHeight+'px');document.getElementById('floating').innerHTML=`<button class="page-fab ${pageDockOpen?'is-open':''}" data-float="page" onclick="pageDockAction()" aria-expanded="${pageDockOpen}" aria-label="${pageDockOpen?(S.page==='home'?'前往工作台':'返回吩咐我'):'展开页面切换'}" title="点击展开，长按上下移动"><span class="dock-grip" aria-hidden="true">‹</span><span class="dock-destination">${S.page==='home'?'工作台':'吩咐我'}<span aria-hidden="true">${S.page==='home'?' →':' ↩'}</span></span></button>${S.drafts?.length?`<button class="draft-fab" onclick="showDrafts()" aria-label="查看暂存">${icon('draft')}<b>${S.drafts.length}</b></button>`:''}<button data-float="voice" title="点击说话，长按拖动" class="floating-voice dictation-button ${listening?'is-listening':''}" onclick="openVoice()" aria-pressed="${listening}" aria-label="${listening?'结束语音演示':'开始语音演示，无需长按'}">${listening?'<span class="dictation-wave"><i></i><i></i><i></i><i></i></span><small>结束</small>':icon('mic')+'<small>吩咐我</small>'}</button>`;const status=document.getElementById('composer-status');if(status)status.textContent=listening?'语音演示 · 正在转成文字':'语音演示 · 点击开始，再点结束';};
sendInput=function(){if(listening)stopDictation();const text=(document.getElementById('input')?.value||S.dictationText||'').trim();if(!text)return;processInput(text,inputContext);S.dictationText='';voiceText='';input='';inputContext='';composerVisible=false;composerExpanded=false;save();go('home');document.getElementById('main').scrollTop=999999;};
const v8SaveDraft=saveVoiceDraft;
saveVoiceDraft=function(){v8SaveDraft();S.dictationText='';input='';save();render();};
function storeInlineDraft(){if(listening)stopDictation();const text=(document.getElementById('input')?.value||S.dictationText||'').trim();if(!text)return;S.drafts.push({id:'draft_'+Date.now(),rows:prepareRows(text),original:text,at:now().toISOString()});S.dictationText='';input='';voiceText='';composerVisible=false;composerExpanded=false;save();render();}
function drawComposer(){document.getElementById('footer').innerHTML=`${composerVisible?`<div class="compact-input ${composerExpanded?'expanded':''}"><div class="composer-hint"><span id="composer-status">${listening?'语音演示 · 正在转成文字':'语音演示 · 点击开始，再点结束'}</span><div class="composer-tools"><button onclick="toggleComposerSize()" aria-expanded="${composerExpanded}">${composerExpanded?'缩小':'展开'}</button><button onclick="storeInlineDraft()">暂存</button><button onclick="hideComposer()" aria-label="收起输入框">收起</button></div></div><div class="composer"><button class="iconbtn" onclick="chooseFile()" aria-label="添加附件">${icon('plus')}</button><textarea id="input" rows="1" placeholder="有事，吩咐我…" oninput="editDictation(this.value)" onkeydown="if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();sendInput()}">${esc(S.dictationText)}</textarea><button class="send" onclick="sendInput()" aria-label="发送">${icon('arrow')}</button></div></div>`:''}`;}
function toggleComposerSize(){composerExpanded=!composerExpanded;drawComposer();mountVoice();}
function hideComposer(){if(listening)stopDictation();composerVisible=false;composerExpanded=false;drawComposer();mountVoice();}
function openTextComposer(text=''){composerVisible=true;composerExpanded=false;S.dictationText=text||S.dictationText;drawComposer();mountVoice();document.getElementById('input')?.focus();}
render=function(){initWorkbench();reconcile();document.getElementById('brandicon').innerHTML=icon('spark');document.getElementById('brandname').textContent=S.page==='overview'?'小天工作台':'小天';document.getElementById('brand-slogan').hidden=S.page==='overview';document.getElementById('main').style.touchAction=S.page==='home'?'pan-y pinch-zoom':'auto';document.getElementById('main').innerHTML=S.page==='overview'?overview():home();drawComposer();input=S.dictationText;applyTheme();mountVoice();bindWorkbenchGestures();};
const prevDispatch=dispatchVoice;
dispatchVoice=function(){prevDispatch();S.dictationText='';input='';save();render();document.getElementById('main').scrollTop=999999;};
const prevReset=resetAsk;
resetAsk=function(){stopDictation();prevReset();};
function initBoundaryCases(){if(S.v10)return;const day=new Date(now().getTime()+28800000).toISOString().slice(0,10),at=h=>day+'T'+h;const make=(id,title,theme,status,h,person,summary,question)=>({id,title,theme,status,kind:'oneoff',person,source:'user',created:at('08:00'),startedAt:person?null:at(h),scheduledStart:person?at(h):null,summary,result:status==='done'?summary:'',quote:'演示需求：'+title,archive:status==='done'?'pending':null,steps:[{title:person?'准备地点与行程':'整理资料与准备方案',status:'done',summary:person?'地点与出发提示已准备。':'AI 的准备步骤已完成。',at:fmt(at('08:00')),end:fmt(at('08:10'))},{title:person?'由您本人到场':question?.actionLabel||'向您汇报',status:status==='done'?'done':'wait_user',summary}],confirmations:question?[{id:'case_answer',at:at(h),blocking:status!=='done',...question}]:[]});const cases=[
make('case_payment','早餐补货 · 待您支付','家庭购物','done','09:00',false,'已加购牛奶、鸡蛋和面包，示例金额 68 元；请您在购物 App 确认支付。',{question:'购物车准备好了，请您确认支付；不会由 AI 代付。',actionLabel:'请您支付',options:['我已支付','暂不购买']}),
make('case_login','会议纪要 · 需要登录邮箱','工作研究','wait_user','10:00',false,'已准备检索会议邮件，需您完成邮箱登录后继续。',{question:'需要您登录邮箱并完成授权，AI 才能读取会议链接。',actionLabel:'请您登录',options:['演示：已完成登录','暂缓处理']}),
make('case_confirm','家人车票 · 确认出发站','家人出行','wait_user','14:00',false,'已整理两条路线，请确认从哪个车站出发；暂不订票。',{question:'请确认出发站，确认后只继续查询，不自动购票。',actionLabel:'请您确认',options:['广州南站','广州站']}),
make('case_meeting','15:00 到 38 层参加讨论','工作研究','todo','15:00',true,'地点和材料已备好，需要您本人到会议室参加讨论。'),
make('case_pickup','19:00 去南站接奶奶','家人出行','todo','19:00',true,'停车位置与接站路线已整理，需要您开车到场接人。')];
for(const t of cases){if(t.id==='case_payment')t.steps=[{title:'整理商品并加入购物车',status:'done',summary:'已模拟加购牛奶、鸡蛋和面包，金额 68 元。',at:fmt(at('08:50')),end:fmt(at('09:00'))},{title:'汇报告知并交接支付',status:'done',summary:'已通知您核对购物车并自行支付；未代付。',at:fmt(at('09:00')),end:fmt(at('09:01'))}];if(!item(t.id))S.items.push(t);}for(const t of [item('relax'),...S.instances.filter(x=>x.parent==='relax')].filter(Boolean))t.person=false;S.v10=true;}
const beforeBoundaryInit=initWorkbench;
initWorkbench=function(){beforeBoundaryInit();initBoundaryCases();};
const beforeBoundaryAnswer=answerConfirmation;
answerConfirmation=function(id,qid,i){beforeBoundaryAnswer(id,qid,i);if(qid==='case_answer'){const t=entity(id),q=t.confirmations.find(q=>q.id===qid);if(q?.answer&&id!=='case_payment'){if(i===1&&id==='case_login'){pause(id);return;}t.summary=id==='case_login'?'已模拟收到邮箱登录授权，继续查找会议链接与准备纪要。':'已确认出发站，继续查询班次；订票前再请您确认。';save();refreshPreserving();}}};
const previousIconHelp=iconHelp;
iconHelp=function(){sheet('协助与线下参加',`<div class="icon-guide"><p>${icon('once')} 一次性任务</p><p>${icon('repeat')} 周期 / 持续任务</p><p>${icon('person')} 本人到场或必须线下完成</p></div><p class="small">需您协助：登录授权、确认资料、审批方案、下单支付。支付不是线下参加。</p><p class="small">线下参加：到会议室开会、开车接人、到社区接种等。在线会议不属于这一类。</p><p class="small muted">任务可以由 AI 完成准备，但仍等待您支付；这时保留“AI 已完成”，另外写清“请您支付”。两类任务都能打开详情查看下一步。</p>`);};
initWorkbench();save();render();


function topicTabs(){return `<div class="topic-tabs" role="tablist" aria-label="任务主题与主动关心">${[['all','全部主题'],['care','主动关心']].map(([key,label])=>`<button role="tab" aria-selected="${(S.topicTab||'all')===key}" class="${(S.topicTab||'all')===key?'selected':''}" onclick="setTopicTab('${key}')">${label}</button>`).join('')}</div>`;}
function setTopicTab(tab){S.topicTab=tab;const scroll=document.getElementById('main').scrollTop;save();render();document.getElementById('main').scrollTop=scroll;}
function carePanel(){return careGroup().replace(/<details[^>]*>/,'<section class="topic-fold care-fold care-panel">').replace('<summary>','<div class="care-summary">').replace('</summary>','</div>').replace('</details>','</section>').replace('主动关怀','主动关心').replace('<i>⌄</i>','');}
